package com.bank.landing;

import java.nio.file.FileSystems;
import java.nio.file.Path;
import java.nio.file.PathMatcher;
import java.util.logging.Logger;

// Compiles a glob like "trades_*.csv" and matches it against a file NAME only.
class GlobMatcher {
    private static final Logger log = Logger.getLogger(GlobMatcher.class.getName());

    private final PathMatcher matcher;
    private final String pattern;

    GlobMatcher(String glob) {
        this.pattern = glob;
        this.matcher = FileSystems.getDefault().getPathMatcher("glob:" + glob);
        log.info(() -> "pathGlobFilter compiled: " + glob);
    }

    boolean matches(Path file) {
        boolean ok = matcher.matches(file.getFileName()); // match on NAME component only
        if (!ok) log.fine(() -> "Skip (name does not match " + pattern + "): " + file.getFileName());
        return ok;
    }
}
