package com.bank.landing;

import java.nio.file.Path;
import java.util.logging.Logger;

// Partition discovery: extract the partition column value from a folder name like trade_date=2026-10-30.
class PartitionDiscoverer {
    private static final Logger log = Logger.getLogger(PartitionDiscoverer.class.getName());

    private final String partitionColumn;

    PartitionDiscoverer(String partitionColumn) { this.partitionColumn = partitionColumn; }

    // Given a data file path, find the partition value from its parent folder.
    String discover(Path dataFile) {
        Path parent = dataFile.getParent();
        String folder = parent.getFileName().toString();     // e.g. trade_date=2026-10-30
        String prefix = partitionColumn + "=";
        if (folder.startsWith(prefix)) {
            String value = folder.substring(prefix.length());
            log.fine(() -> "Discovered " + partitionColumn + "=" + value + " for " + dataFile.getFileName());
            return value;
        }
        return null;
    }
}
