package com.bank.landing;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;
import java.util.stream.Stream;

// Lists files under partition folders, applies pathGlobFilter, derives partition columns.
class LandingReader {
    private static final Logger log = Logger.getLogger(LandingReader.class.getName());

    private final GlobMatcher glob;
    private final PartitionDiscoverer discoverer;

    LandingReader(GlobMatcher glob, PartitionDiscoverer discoverer) {
        this.glob = glob;
        this.discoverer = discoverer;
    }

    // Returns the list of files actually read, each tagged with its derived partition value.
    List<String> read(Path basePath) throws IOException {
        List<String> readFiles = new ArrayList<>();
        int skipped = 0;
        try (Stream<Path> walk = Files.walk(basePath)) {
            List<Path> files = walk.filter(Files::isRegularFile).sorted().toList();
            for (Path file : files) {
                if (!glob.matches(file)) {
                    skipped++;
                    log.warning(() -> "SKIPPED by pathGlobFilter: " + file.getFileName());
                    continue;
                }
                String partitionValue = discoverer.discover(file);
                readFiles.add(file.getFileName() + " [trade_date=" + partitionValue + "]");
                log.info(() -> "READ " + file.getFileName() + " with trade_date=" + partitionValue);
            }
        }
        int finalSkipped = skipped;
        log.info(() -> "Done. Read " + readFiles.size() + " data files, skipped " + finalSkipped + " non-data files");
        return readFiles;
    }
}
