package com.bank.landing;

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.logging.Logger;

public class LandingDemo {
    private static final Logger log = Logger.getLogger(LandingDemo.class.getName());

    public static void main(String[] args) throws IOException {
        Path base = Path.of(System.getProperty("java.io.tmpdir"), "nbi-landing", "trades");

        // Build a partitioned landing directory with mixed files.
        createPartition(base.resolve("trade_date=2026-10-29"),
            "trades_0001.csv", "trades_0002.csv", "_SUCCESS", "manifest.json");
        createPartition(base.resolve("trade_date=2026-10-30"),
            "trades_0003.csv", "upload.tmp", "trades_0004.csv");

        GlobMatcher glob = new GlobMatcher("trades_*.csv");
        PartitionDiscoverer discoverer = new PartitionDiscoverer("trade_date");
        LandingReader reader = new LandingReader(glob, discoverer);

        List<String> read = reader.read(base);
        log.info(() -> "Files that became DataFrame input: " + read);
    }

    private static void createPartition(Path dir, String... fileNames) throws IOException {
        Files.createDirectories(dir);
        for (String name : fileNames) {
            Files.writeString(dir.resolve(name), "TRD,SAV2001,RELIANCE,100\n");
        }
    }
}
